SELECT 'f3103caf-5054-5390-a1ff-dd99edd3fb86', e.`id`, 81, 'Em determinada reclamação trabalhista, o preposto da empresa reclamada não soube responder às perguntas formuladas pelo juiz e pelo advogado do reclamante na audiência de instrução e argumentou que não possuía conhecimento específico a respeito dos fatos que estavam sendo tratados no processo. O advogado da empresa juntou à contestação diversos documentos na audiência inaugural. Nessa situação hipotética,', '{"a":"a prova pré-constituída nos autos pode ser considerada para o confronto com a confissão ficta.","b":"a empresa deve ser declarada confessa, independentemente de ter juntado defesa e documentos.","c":"o juiz, antes de aplicar a penalidade de confissão, deve determinar à empresa que apresente novas provas ao processo.","d":"o juiz deve designar nova audiência, determinando que a empresa nomeie preposto que conheça os fatos abordados no processo."}', 'a', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Processual do Trabalho' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Processual do Trabalho' AND ss.`name` = 'Reclamação Trabalhista e Audiência' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 81);--> statement-breakpoint
