SELECT '08d162a2-b4f8-5f1f-aa97-203334638cb9', e.`id`, 82, 'Na hipótese de um empregado desejar mover ação de reparação de perdas e danos causados pelo cálculo incorreto do benefício previdenciário por omissão ou equívoco do empregador, o processamento e o julgamento da demanda competirão', '{"a":"à justiça do trabalho.","b":"à justiça federal.","c":"à justiça comum estadual.","d":"ao Ministério da Previdência Social."}', 'a', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Processual do Trabalho' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Processual do Trabalho' AND ss.`name` = 'Organização e Competência da Justiça do Trabalho' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 82);--> statement-breakpoint
INSERT INTO `exam_questions` (`id`, `exam_id`, `number`, `statement`, `alternatives`, `correct_answer`, `subject_id`, `subsubject_id`, `ebook_topic_id`, `difficulty`, `classified`, `classified_at`)
SELECT '90392ce1-c4f6-5d70-adda-54b0fd91032f', e.`id`, 83, 'Assinale opção correta de acordo com as normas constitucionais sobre zoneamento ambiental.', '{"a":"Os estados podem, por lei complementar, instituir regiões metropolitanas, aglomerações urbanas e microrregiões, com a finalidade de integrar a organização, o planejamento e a execução de funções públicas de interesse comum. Para isso, precisam da concordância dos municípios envolvidos, os quais devem aprovar leis municipais com o mesmo teor e conteúdo da lei estadual.","b":"Compete à União elaborar planos nacionais e regionais de ordenação do território e de desenvolvimento econômico e social.","c":"As zonas de uso predominantemente industrial destinam-se, preferencialmente, à localização de estabelecimentos industriais cujos resíduos sólidos, líquidos e gasosos, ruídos, vibrações e radiações possam causar danos à saúde, ao bem-estar e à segurança das populações, mesmo depois da aplicação de métodos adequados de combate e tratamento de efluentes.","d":"É da competência dos estados a promoção, no que couber, do adequado ordenamento territorial mediante planejamento e controle do uso, do parcelamento e da ocupação do solo urbano."}', 'b', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Ambiental' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Ambiental' AND ss.`name` = 'Princípios e Política Nacional do Meio Ambiente' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 83);--> statement-breakpoint
INSERT INTO `exam_questions` (`id`, `exam_id`, `number`, `statement`, `alternatives`, `correct_answer`, `subject_id`, `subsubject_id`, `ebook_topic_id`, `difficulty`, `classified`, `classified_at`)
SELECT '1b411312-5754-5b95-ac5f-70f899c36ccb', e.`id`, 84, 'Relativamente à tutela penal do meio ambiente, assinale a opção correta.', '{"a":"Não constitui crime o abate de animal quando realizado, entre outras hipóteses, em estado de necessidade, para saciar a fome do agente ou de sua família.","b":"Constitui crime matar, perseguir, caçar, apanhar ou utilizar espécimes da fauna silvestre sem a devida permissão, licença ou autorização da autoridade competente. Tal proibição não alcança, entretanto, os espécimes em rota migratória que não sejam nativos.","c":"Comprovada a responsabilidade de pessoa jurídica na prática de crime ambiental, ficará automaticamente excluída a responsabilidade das pessoas físicas, autoras, coautoras ou partícipes do mesmo fato.","d":"Os animais ilegalmente caçados que forem apreendidos deverão ser libertados em seu habitat, não podendo ser entregues a jardins zoológicos ou a entidades similares."}', 'a', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Ambiental' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Ambiental' AND ss.`name` = 'Responsabilidade Ambiental' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 84);--> statement-breakpoint
INSERT INTO `exam_questions` (`id`, `exam_id`, `number`, `statement`, `alternatives`, `correct_answer`, `subject_id`, `subsubject_id`, `ebook_topic_id`, `difficulty`, `classified`, `classified_at`)
SELECT 'c0330c99-86ef-5ea0-aa73-322058472701', e.`id`, 85, 'No que se refere às penas restritivas de direitos e à de multa, assinale a opção correta.', '{"a":"Se o condenado for reincidente, o juiz não poderá aplicar a substituição da pena privativa de liberdade, apesar de, em face de condenação anterior, a medida ser socialmente recomendável e a reincidência não se ter operado em virtude da prática do mesmo crime.","b":"A prestação de serviços à comunidade ou a entidades públicas consiste na atribuição de tarefas gratuitas ao condenado, sendo aplicável às condenações superiores a seis meses de privação da liberdade, atendidos os demais requisitos legais.","c":"A limitação de fim de semana consiste na obrigação de permanência, aos sábados, domingos e feriados, por oito horas diárias, em casa de albergado ou em outro estabelecimento adequado.","d":"A pena de multa consiste no pagamento, ao fundo penitenciário, da quantia determinada na sentença e calculada em dias-multa, sendo, no mínimo, de dez e, no máximo, de trezentos e sessenta e cinco dias-multa, a ser fixada pelo juiz, não podendo ser inferior a um trigésimo do maior salário mínimo mensal vigente ao tempo do fato, nem superior a cinco vezes esse salário."}', 'b', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Penal' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Penal' AND ss.`name` = 'Penas e Extinção da Punibilidade' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 85);--> statement-breakpoint
INSERT INTO `exam_questions` (`id`, `exam_id`, `number`, `statement`, `alternatives`, `correct_answer`, `subject_id`, `subsubject_id`, `ebook_topic_id`, `difficulty`, `classified`, `classified_at`)
SELECT '196b8b1e-461b-571f-a236-f13991b05204', e.`id`, 86, 'Com relação à pena de multa, assinale a opção correta.', '{"a":"Transitada em julgado a sentença condenatória, a multa será considerada dívida de valor, aplicando-se-lhe as normas da legislação relativa à dívida ativa da fazenda pública, exceto no que concerne às causas interruptivas e suspensivas da prescrição, incidindo, nesse caso, as normas do CP.","b":"Sobrevindo ao condenado doença mental, é suspensa a execução da pena de multa.","c":"Transitada em julgado a sentença condenatória, a multa deverá ser paga no prazo de dez dias e será convertida em pena privativa de liberdade caso o condenado não realize o pagamento.","d":"É vedado o pagamento da pena de multa em parcelas mensais, dada a natureza jurídica de tal espécie de sanção."}', 'b', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Penal' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Penal' AND ss.`name` = 'Penas e Extinção da Punibilidade' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 86);--> statement-breakpoint
INSERT INTO `exam_questions` (`id`, `exam_id`, `number`, `statement`, `alternatives`, `correct_answer`, `subject_id`, `subsubject_id`, `ebook_topic_id`, `difficulty`, `classified`, `classified_at`)
SELECT 'b2b5488b-aca0-536a-a07a-23db5b436581', e.`id`, 87, 'Em relação à imputabilidade penal, assinale a opção correta.', '{"a":"Quanto à aferição da inimputabilidade, o CP adota, como regra, o critério psicológico, segundo o qual importa saber se o agente, no momento da ação ou da omissão delituosa, tem ou não condições de avaliar o caráter criminoso do fato e de orientar-se de acordo com esse entendimento.","b":"A pena poderá ser reduzida se o agente, em virtude de perturbação de saúde mental ou por desenvolvimento mental incompleto ou retardado, não for inteiramente capaz de entender o caráter ilícito do fato ou de determinar-se de acordo com esse entendimento.","c":"A pena imposta ao semi-imputável não pode ser substituída por medida de segurança.","d":"A embriaguez não acidental, seja voluntária ou culposa, completa ou incompleta, exclui a imputabilidade do agente que, ao tempo da ação ou omissão delituosa, for inteiramente incapaz de entender o caráter ilícito do fato ou de determinar-se de acordo com esse entendimento."}', 'b', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Penal' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Penal' AND ss.`name` = 'Teoria Geral do Crime' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 87);--> statement-breakpoint
INSERT INTO `exam_questions` (`id`, `exam_id`, `number`, `statement`, `alternatives`, `correct_answer`, `subject_id`, `subsubject_id`, `ebook_topic_id`, `difficulty`, `classified`, `classified_at`)
SELECT 'd7296d71-7cf7-5019-af8b-f56d532340e7', e.`id`, 88, 'Com relação aos crimes contra o patrimônio, assinale a opção correta.', '{"a":"A conduta da vítima não é fator de distinção entre os delitos de roubo e extorsão.","b":"O crime de extorsão mediante sequestro consuma-se no momento em que o resgate é exigido, independentemente do momento da privação da liberdade da vítima.","c":"Ocorre crime de extorsão indireta quando alguém, abusando da situação de outro, exige, como garantia de dívida, documento que pode dar causa a procedimento criminal contra a vítima ou terceiro.","d":"No crime de apropriação indébita, o fato de o agente praticá-lo em razão de ofício, emprego ou profissão não interfere na imposição da pena, por se tratar de elementar do tipo."}', 'c', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Penal' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Penal' AND ss.`name` = 'Crimes em Espécie' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 88);--> statement-breakpoint
INSERT INTO `exam_questions` (`id`, `exam_id`, `number`, `statement`, `alternatives`, `correct_answer`, `subject_id`, `subsubject_id`, `ebook_topic_id`, `difficulty`, `classified`, `classified_at`)
SELECT '11ce397b-3d7f-50b2-ad21-d452652359de', e.`id`, 89, 'Considere que Charles, funcionário público no exercício de suas funções, tenha desviado dolosamente valores particulares de que tinha a posse em razão do cargo. Nessa situação hipotética,', '{"a":"Charles praticou crime de furto, e não de peculato, haja vista que os valores de que tinha a posse em razão do cargo eram particulares, e não, públicos.","b":"se Charles reparar o dano antes do recebimento da denúncia, sua punibilidade será extinta; se o fizer posteriormente, sua pena será diminuída.","c":"a pena de Charles não seria alterada na eventualidade de ser ele ocupante de cargo em comissão de órgão da administração direta, visto que a tipificação do crime já considera o fato de ser o agente funcionário público como elementar do tipo.","d":"Charles praticou peculato-desvio, podendo eventual reparação do dano ser considerada arrependimento posterior ou circunstância atenuante genérica, a depender do momento em que for efetivada."}', 'd', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Penal' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Penal' AND ss.`name` = 'Crimes em Espécie' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 89);--> statement-breakpoint
INSERT INTO `exam_questions` (`id`, `exam_id`, `number`, `statement`, `alternatives`, `correct_answer`, `subject_id`, `subsubject_id`, `ebook_topic_id`, `difficulty`, `classified`, `classified_at`)
SELECT 'fb5583f7-d5ac-5aa7-a485-ddf9c5d76d0e', e.`id`, 90, 'Assinale a opção correta acerca da pena cumprida no estrangeiro e da eficácia da sentença estrangeira.', '{"a":"É possível a homologação, pelo STJ, de sentença penal condenatória proferida pela justiça de outro país, para obrigar o condenado residente no Brasil à reparação do dano causado pelo crime que cometeu.","b":"A competência para a homologação de sentença estrangeira é do STF, restringindo-se a referida homologação a casos que envolvam cumprimento de pena privativa de liberdade no Brasil.","c":"Apenas nas hipóteses de infração penal de menor potencial ofensivo, admite-se que a pena cumprida no estrangeiro atenue a pena imposta, no Brasil, pelo mesmo crime.","d":"A pena cumprida no estrangeiro não atenua nem compensa a pena imposta, no Brasil, pelo mesmo crime, dado o caráter independente das justiças nacional e estrangeira."}', 'a', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Penal' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Penal' AND ss.`name` = 'Aplicação da Lei Penal' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 90);--> statement-breakpoint
INSERT INTO `exam_questions` (`id`, `exam_id`, `number`, `statement`, `alternatives`, `correct_answer`, `subject_id`, `subsubject_id`, `ebook_topic_id`, `difficulty`, `classified`, `classified_at`)
SELECT 'ef2f3f42-b8b8-574a-aa68-7432ea2d2ae2', e.`id`, 91, 'Admite-se a suspensão condicional da pena (sursis)', '{"a":"em casos de condenação a pena restritiva de direito ou privativa de liberdade, desde que não superior a quatro anos.","b":"a reincidente em crime doloso, desde que a condenação anterior tenha sido exclusivamente à pena de multa.","c":"para o condenado que, na data do fato, tenha idade acima de setenta anos, desde que a pena não seja superior a dois anos.","d":"para o condenado em estado de saúde grave ou portador de doença incurável, desde que ele tenha reparado o dano."}', 'b', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Penal' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Penal' AND ss.`name` = 'Penas e Extinção da Punibilidade' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 91);--> statement-breakpoint
INSERT INTO `exam_questions` (`id`, `exam_id`, `number`, `statement`, `alternatives`, `correct_answer`, `subject_id`, `subsubject_id`, `ebook_topic_id`, `difficulty`, `classified`, `classified_at`)
SELECT 'efd9190f-d203-53b1-a622-a644ce3ea02e', e.`id`, 92, 'Acerca da competência no âmbito do direito processual penal, assinale a opção correta.', '{"a":"Caso um policial militar cometa, em uma mesma comarca, dois delitos conexos, um cujo processo e julgamento seja de competência da justiça estadual militar e o outro, da justiça comum estadual, haverá cisão processual.","b":"Os desembargadores dos tribunais de justiça dos estados e dos tribunais regionais federais possuem prerrogativa de foro especial, devendo ser processados e julgados criminalmente no STF.","c":"A competência para processo e julgamento por crime de contrabando ou descaminho define-se pela prevenção do juízo federal do local por onde as mercadorias sejam indevidamente introduzidas no Brasil.","d":"Caso um indivíduo tenha cometido, em uma mesma comarca, dois delitos conexos, um cujo processo e julgamento seja da competência da justiça federal e o outro, da justiça comum estadual, a competência para o julgamento unificado dos dois crimes será determinada pelo delito considerado mais grave."}', 'a', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Processual Penal' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Processual Penal' AND ss.`name` = 'Processo Penal Geral' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 92);--> statement-breakpoint
INSERT INTO `exam_questions` (`id`, `exam_id`, `number`, `statement`, `alternatives`, `correct_answer`, `subject_id`, `subsubject_id`, `ebook_topic_id`, `difficulty`, `classified`, `classified_at`)
SELECT '800cc82a-066b-58d9-ab28-7aa9753be6eb', e.`id`, 93, 'Maurício foi denunciado pela prática do delito de estelionato perante a 1.ª Vara Criminal de Justiça de Belo Horizonte – MG. Por entender que não havia justa causa para a ação penal, o advogado contratado pelo réu impetrou habeas corpus perante o TJ/MG, que, por maioria de votos, denegou a ordem. Nessa situação hipotética, em face da inexistência de ambiguidade, omissão, contradição, ou obscuridade no acórdão, caberá recurso', '{"a":"ordinário constitucional ao STJ.","b":"ordinário constitucional ao STF.","c":"especial ao STJ e(ou) recurso extraordinário ao STF, conforme o teor da fundamentação do acórdão.","d":"de embargos infringentes e de nulidade ao grupo criminal competente do TJ/MG."}', 'a', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Processual Penal' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Processual Penal' AND ss.`name` = 'Recursos no Processo Penal' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 93);--> statement-breakpoint
INSERT INTO `exam_questions` (`id`, `exam_id`, `number`, `statement`, `alternatives`, `correct_answer`, `subject_id`, `subsubject_id`, `ebook_topic_id`, `difficulty`, `classified`, `classified_at`)
SELECT '6ea9c547-f814-5884-a5ed-9846ae8081f0', e.`id`, 94, 'Acerca da ação civil ex delicto, assinale a opção correta.', '{"a":"A execução da sentença penal condenatória no juízo cível é ato personalíssimo do ofendido e não se estende aos seus herdeiros.","b":"Ao proferir sentença penal condenatória, o juiz fixará valor mínimo para a reparação dos danos causados pela infração, considerando os prejuízos sofridos pelo ofendido, sem prejuízo da liquidação para apuração do dano efetivamente sofrido.","c":"Segundo o CPP, a sentença absolutória no juízo criminal impede a propositura da ação civil para reparação de eventuais danos resultantes do fato, uma vez que seria contraditório absolver o agente na esfera criminal e processá-lo no âmbito cível.","d":"O despacho de arquivamento do inquérito policial e a decisão que julga extinta a punibilidade são causas impeditivas da propositura da ação civil."}', 'b', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Processual Penal' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Processual Penal' AND ss.`name` = 'Ação Penal' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 94);--> statement-breakpoint
INSERT INTO `exam_questions` (`id`, `exam_id`, `number`, `statement`, `alternatives`, `correct_answer`, `subject_id`, `subsubject_id`, `ebook_topic_id`, `difficulty`, `classified`, `classified_at`)
SELECT '75228b5d-1d67-552c-af1c-6f362eea636f', e.`id`, 95, 'Márcio foi denunciado pelo crime de bigamia. O advogado de defesa peticionou ao juízo criminal requerendo a suspensão da ação penal, por entender que o primeiro casamento de Márcio padecia de nulidade, fato que gerou ação civil anulatória, em trâmite perante o juízo cível da mesma comarca. Nessa situação hipotética,', '{"a":"deverá o juízo criminal, de ofício, extinguir a punibilidade de Márcio, uma vez que o delito de bigamia foi revogado.","b":"considerando-se a independência das instâncias, o processo criminal deverá ter seguimento independentemente do desfecho da ação anulatória civil.","c":"apesar de as instâncias cível e criminal serem independentes, o juízo criminal poderá, por cautela, determinar a suspensão da ação penal até que se resolva, no juízo cível, a controvérsia relativa à nulidade do primeiro casamento de Márcio.","d":"a ação penal deverá ser suspensa até que a nulidade do primeiro casamento de Márcio seja resolvida definitivamente no juízo cível."}', 'd', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Processual Penal' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Processual Penal' AND ss.`name` = 'Procedimentos e Julgamento' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 95);--> statement-breakpoint
