SELECT '751d839a-2ea9-5b47-af18-7a19d475afff', e.`id`, 96, 'Com relação aos meios de prova no processo penal, assinale a opção correta de acordo com o CPP.', '{"a":"Se o juiz tiver notícia da existência de documento relativo a ponto relevante da acusação ou da defesa, não poderá providenciar, independentemente de requerimento das partes, a juntada aos autos, uma vez que é mero espectador do processo, sem atuação de oficio na gestão da prova.","b":"Em regra, a testemunha não pode eximir-se da obrigação de depor. No entanto, o cônjuge do acusado à época do fato criminoso, ainda que dele se encontre separado judicialmente, pode recusar-se a testemunhar.","c":"Em regra, as partes deverão apresentar os documentos necessários à comprovação de suas alegações na primeira oportunidade que falarem nos autos, sob pena de preclusão.","d":"O procedimento de acareação só será admitido entre acusados, sendo vedada a acareação entre acusado e testemunha."}', 'b', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Processual Penal' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Processual Penal' AND ss.`name` = 'Provas no Processo Penal' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 96);--> statement-breakpoint
