SELECT '403421ba-d7f9-5acf-a74b-f72025191282', e.`id`, 97, 'Considerando as disposições processuais penais previstas na Lei federal n.º 9.099/1995 (Lei dos Juizados Especiais), assinale a opção correta.', '{"a":"Os processos referentes aos juizados especiais criminais devem orientar-se pelos critérios de oralidade, documentação, simplicidade, formalidade, economia processual e celeridade, em busca, sempre que possível, da conciliação ou da transação.","b":"O juizado especial criminal, provido por juízes togados ou togados e leigos, tem competência apenas para a conciliação e o julgamento das infrações penais de menor potencial ofensivo, respeitadas as regras de conexão e continência.","c":"Na reunião de processos, perante o juízo comum ou o tribunal do júri, decorrente da aplicação das regras de conexão e continência, serão observados os institutos da transação penal, excluindo-se os da composição dos danos civis.","d":"Os atos processuais serão públicos e poderão realizar-se em horário noturno e em qualquer dia da semana, conforme dispuserem as normas de organização judiciária."}', 'd', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Processual Penal' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Processual Penal' AND ss.`name` = 'Procedimentos e Julgamento' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 97);--> statement-breakpoint
