SELECT '6c7a1c89-f956-50d1-a8e1-ddb92e64609f', e.`id`, 98, 'Carlos, empresário reconhecidamente bem-sucedido, foi denunciado por crime contra a ordem tributária. No curso da ação penal, seu advogado constituído renunciou ao mandato procuratório. Devidamente intimado para constituir novo advogado, Carlos não o fez, tendo o juiz nomeado defensor dativo para patrocinar sua defesa. Nessa hipótese, de acordo com o que dispõe o CPP, Carlos', '{"a":"será obrigado, por não ser pobre, a pagar os honorários do defensor dativo, arbitrados pelo juiz.","b":"será obrigado, por não ser pobre, a pagar os honorários do defensor dativo, arbitrados pelo próprio defensor.","c":"será obrigado, por não ser pobre, a pagar os honorários do defensor dativo, os quais deverão ser postulados em ação própria no juízo cível da comarca onde tenha tramitado a ação penal.","d":"estará desobrigado do pagamento dos honorários advocatícios, visto que é incabível o arbitramento de honorários ao defensor dativo, ainda que o réu não seja pobre."}', 'a', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Processual Penal' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Processual Penal' AND ss.`name` = 'Processo Penal Geral' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
