SELECT '3ebbba5e-bca0-5286-ad7d-6eea2a13cd47', e.`id`, 99, 'Considerando o que dispõe o Estatuto da Criança e do Adolescente, assinale a opção correta.', '{"a":"O vínculo da adoção constitui-se por sentença judicial, que será inscrita no registro civil mediante mandado, do qual se fornecerá, administrativamente, certidão somente ao adotado e aos pais, biológicos e adotivos, à vista de documentação comprobatória.","b":"É dever do Estado assegurar atendimento gratuito, em creche e pré-escola, às crianças de zero a sete anos de idade.","c":"É proibida a venda de bilhetes da Mega-Sena a crianças e adolescentes.","d":"Criança ou adolescente desacompanhados dos pais ou do responsável estão proibidos de viajar para fora da comarca onde residem, sem expressa autorização judicial."}', 'c', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito da Criança e do Adolescente' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito da Criança e do Adolescente' AND ss.`name` = 'Princípios e Proteção Integral' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
