SELECT '4f1f0956-cf00-5299-ae90-362547d87250', e.`id`, 100, 'Assinale a opção correta no que se refere à família substituta.', '{"a":"A colocação em família substituta ocorrerá mediante guarda, tutela, curatela ou adoção, conforme a situação jurídica da criança ou adolescente, o que só poderá ser reconhecido e determinado pelo juiz da vara da infância e da adolescência.","b":"Sempre que possível, a criança ou adolescente deverá ser previamente ouvido, e a sua opinião, devidamente considerada.","c":"Na apreciação do pedido de adoção, o grau de parentesco e a relação de afinidade ou de afetividade devem ser considerados, a fim de que sejam evitadas ou minoradas as consequências decorrentes da medida, o que não ocorre nos casos de guarda provisória e tutela, para cuja concessão o conselho tutelar considera requisito apenas a certidão de bons antecedentes da família substituta.","d":"Não se deferirá a colocação da criança ou do adolescente em família substituta à pessoa que apresente, por prazo superior a 180 dias, limitações em sua capacidade laborativa."}', 'b', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito da Criança e do Adolescente' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito da Criança e do Adolescente' AND ss.`name` = 'Família Substituta e Adoção' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 1 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 100);--> statement-breakpoint
