SELECT 'dbd66225-b492-5cd9-ae0e-f55564da3108', e.`id`, 81, 'Renato, advogado em início de carreira, é contactado para defender os interesses de Rodrigo que está detido em cadeia pública. Dirige-se ao local onde seu cliente está retido e busca informações sobre sua situação, recebendo como resposta do servidor público que estava de plantão que os autos do inquérito estariam conclusos com a autoridade policial e, por isso, indisponíveis para consulta e que deveria o advogado retornar quando a autoridade tivesse liberado os autos para realização de diligências. À luz das normas aplicáveis,', '{"a":"o advogado, diante do seu dever de urbanidade, deve aguardar os atos cabíveis da autoridade policial.","b":"o acesso aos autos, no caso, depende de procuração e de prévia autorização da autoridade policial.","c":"no caso de réu preso, somente com autorização do juiz pode o advogado acessar os autos do inquérito policial.","d":"o acesso aos autos de inquérito policial é direito do advogado, mesmo sem procuração ou conclusos à autoridade policial."}', 'd', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND ss.`name` = 'Prerrogativas e Imunidades' LIMIT 1), (SELECT t.`id` FROM `ebook_topics` t JOIN `subjects` s ON s.`id` = t.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND t.`order` = 1 LIMIT 1), 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 2 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 81);--> statement-breakpoint
