SELECT '1de7c8b8-7fc3-5009-a2b0-7700aa94fcb1', e.`id`, 82, 'Mauro, advogado com larga experiência profissional, resolve contratar com emissora de televisão, um novo programa, incluído na grade normal de horários da empresa, cujo titulo é “o Advogado na TV”, com o fito de proporcionar informações sobre a carreira, os seus percalços, suas angústias, alegrias e comprovar a possibilidade de sucesso profissional. No curso do programa, inclui referência às causas ganhas, bem como àquelas ainda em curso e que podem ter repercussão no meio jurídico, todas essas vinculadas ao seu escritório de advocacia. Consoante as normas aplicáveis, é correto afirmar que:', '{"a":"a participação em programa televisivo está vedada aos advogados.","b":"a publicidade, como narrada, é compatível com as normas do Código de Ética.","c":"o advogado, no caso, deveria se limitar ao aspecto educacional e instrutivo da atividade profissional.","d":"programas televisivos são franqueados aos advogados, inclusive para realizar propaganda dos seus escritórios."}', 'c', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND ss.`name` = 'Ética e Estatuto da Advocacia' LIMIT 1), (SELECT t.`id` FROM `ebook_topics` t JOIN `subjects` s ON s.`id` = t.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND t.`order` = 6 LIMIT 1), 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 2 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 82);--> statement-breakpoint
