SELECT 'e51d5e7c-dc12-59ad-a6fb-68a1413775d1', e.`id`, 83, 'Fábio, advogado com mais de dez anos de efetiva atividade, obtém a indicação da OAB para concorrer pelo quinto constitucional à vaga reservada no âmbito de Tribunal de Justiça. No curso do processo também obtém a indicação do Tribunal e vem a ser nomeado pelo Governador do Estado, ingressando nos quadros do Poder Judiciário. Diante disso, à luz das normas estatutárias ocorrerá:', '{"a":"o cancelamento da inscrição como advogado.","b":"a suspensão até que cesse a incompatibilidade.","c":"o licenciamento do profissional.","d":"a passagem para a reserva do quadro de advogados."}', 'a', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND ss.`name` = 'Inscrição e Exercício da Advocacia' LIMIT 1), (SELECT t.`id` FROM `ebook_topics` t JOIN `subjects` s ON s.`id` = t.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND t.`order` = 8 LIMIT 1), 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 2 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 83);--> statement-breakpoint
