SELECT '49762548-098e-5fa7-aaa4-a88743970843', e.`id`, 84, 'João Vítor e Ana Beatriz, ambos advogados, contraem núpcias, mantendo o estado de casados por longos anos. Paralelamente, também mantêm sociedade em escritório de advocacia. Por motivos vários, passam a ter seguidas altercações, com acusações mútuas de descumprimento dos deveres conjugais. Ana Beatriz, revoltada com as acusações desfechadas por João Vítor, requer que a OAB promova sessão de desagravo, uma vez que sua honra foi atingida por seu marido, em discussões conjugais. À luz das normas estatutárias,', '{"a":"nenhum ato poderá ser realizado pela OAB, tendo em vista que as ofensas não ocorreram no exercício da profissão de advogado.","b":"o ato de desagravo depende somente da qualidade de advogado do ofendido.","c":"sendo o ofensor advogado, o desagravo é permitido pelo estatuto.","d":"o desagravo poderá ocorrer privadamente."}', 'a', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND ss.`name` = 'Prerrogativas e Imunidades' LIMIT 1), (SELECT t.`id` FROM `ebook_topics` t JOIN `subjects` s ON s.`id` = t.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND t.`order` = 1 LIMIT 1), 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 2 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 84);--> statement-breakpoint
