SELECT '315083b9-ddaa-52c9-ac40-57083b91cf3c', e.`id`, 85, 'Francisco, advogado, dirige-se, com seu cliente, para participar de audiência em questão cível, designada para a colheita de provas e depoimento pessoal. O ato fora designado para iniciar às 13 horas. Como é de praxe, adentraram o recinto forense com meia hora de antecedência, sendo comunicados pelo Oficial de Justiça que a pauta de audiências continha dez eventos e que a primeira havia iniciado às dez horas, já caracterizado um atraso de uma hora, desde a audiência inaugural. A autoridade judicial encontrava-se presente no foro desde as nove horas da manhã, para despachos em geral, tendo iniciado a primeira audiência no horário aprazado. Após duas horas de atraso, Francisco informou, por escrito, ao Chefe do Cartório Judicial, que, diante do ocorrido, ele e seu cliente estariam se retirando do recinto. Diante do narrado, à luz das normas estatutárias', '{"a":"qualquer atraso superior a uma hora justifica a retirada do recinto, pelo advogado.","b":"o advogado deveria, no caso narrado, peticionar ao Magistrado e retirar-se do recinto.","c":"o atraso que justifica a retirada do advogado está condicionado à ausência da autoridade judicial no evento.","d":"meros atrasos da autoridade judicial não permitem a retirada do advogado do recinto."}', 'c', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND ss.`name` = 'Prerrogativas e Imunidades' LIMIT 1), (SELECT t.`id` FROM `ebook_topics` t JOIN `subjects` s ON s.`id` = t.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND t.`order` = 1 LIMIT 1), 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 2 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 85);--> statement-breakpoint
