SELECT 'd5da5a21-2106-5844-a741-e8e5fd4900a9', e.`id`, 86, 'Dentre as sanções cabíveis no processo disciplinar realizado pela OAB no concernente aos advogados estão a censura, a suspensão, a exclusão e a multa. Dentre as circunstâncias atenuantes para a aplicação do ato sancionatório, encontra-se, consoante o Estatuto,', '{"a":"exercício assíduo e proficiente em mandato realizado na OAB.","b":"ser reincidente em faltas da mesma natureza.","c":"prestação de serviços à advocacia, mesmo irrelevantes.","d":"ter sido o ato cometido contra outro integrante de carreira jurídica."}', 'a', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND ss.`name` = 'Infrações e Sanções Disciplinares' LIMIT 1), (SELECT t.`id` FROM `ebook_topics` t JOIN `subjects` s ON s.`id` = t.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND t.`order` = 3 LIMIT 1), 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 2 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 86);--> statement-breakpoint
