SELECT 'f2055bf1-a6bf-56c0-a610-dbcc573b3b67', e.`id`, 87, 'Eduardo, advogado, é contratado para defender os interesses de Otávio, próspero fazendeiro, em diversas ações, de natureza civil, empresarial, criminal, bem como em processos administrativos que tramitam em numerosos órgãos públicos. Antes de realizar os atos próprios da profissão, apresenta ao cliente os termos de contrato de honorários, que divide em valores fixos, acrescidos dos decorrentes da eventual sucumbência existente nos processos judiciais. À luz das normas aplicáveis,', '{"a":"os honorários sucumbenciais e os contratados são naturalmente excludentes, devendo o profissional optar por um deles.","b":"os honorários contratuais devem ser sempre em valor fixo.","c":"os honorários de sucumbência podem, ao alvedrio das partes, sofrer desconto dos honorários pactuados contratualmente.","d":"os honorários sucumbenciais acrescidos dos honorários contratuais podem superar o benefício econômico obtido pelo cliente."}', 'c', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND ss.`name` = 'Honorários Advocatícios' LIMIT 1), (SELECT t.`id` FROM `ebook_topics` t JOIN `subjects` s ON s.`id` = t.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND t.`order` = 2 LIMIT 1), 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 2 AND e.`year` = 2010
