SELECT 'fe7e15fd-26b5-57da-a6f6-3c026bb052b4', e.`id`, 88, 'Caio, advogado, inscrito na OAB-SP, após aprovação em concorrido Exame de Ordem, atua em diversos ramos do Direito. Um dos seus clientes possui causa em curso perante a Comarca de Tombos/MG, tendo o profissional comparecido à sede do Juízo para praticar ato em prol do seu constituinte. Estando no local, foi surpreendido por designação do Juiz Titular da Comarca para representar Tício, pessoa de parcos recursos financeiros, diante da ausência de Defensor Público designado para prestar serviços no local, por falta de efetivo suficiente de profissionais. Não tendo argumentos para recusar o encargo, Caio participou do ato. Diante desse quadro', '{"a":"o ato deveria ter sido adiado diante da exclusividade da atuação da Defensoria Pública.","b":"o advogado deveria ter recusado o encargo, mesmo sem justificativa plausível.","c":"a recusa nesses casos poderá ocorrer, com justo motivo.","d":"a recusa poderia ocorrer diante da ausência de sanção disciplinar."}', 'c', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND ss.`name` = 'Infrações e Sanções Disciplinares' LIMIT 1), (SELECT t.`id` FROM `ebook_topics` t JOIN `subjects` s ON s.`id` = t.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND t.`order` = 3 LIMIT 1), 'medium', true, NOW()
