SELECT 'c5e11e75-26ba-5882-a924-f65cc9a13bee', e.`id`, 89, 'Michel, Philippe e Lígia, bacharéis em Direito recém-formados e colegas de bancos universitários, comprometem-se a empreender a atividade advocatícia de forma conjunta logo após a aprovação no Exame de Ordem. Para gáudio dos bacharéis, todos são aprovados no certame e obtém sua inscrição no Quadro de Advogados da OAB. Assim, alugam sala compatível em local próximo ao prédio do Fórum do município onde pretendem exercer sua nobre função. De início, as causas são individuais, por indicação de amigos e parentes. Logo, no entanto, diante do sucesso profissional alcançado, são contactados por sociedades empresárias ansiosas pela prestação de serviços profissionais advocatícios de qualidade. Uma exigência, no entanto, é realizada: a prestação deve ocorrer por meio de sociedade de advogados. No concernente ao tema, à luz das normas aplicáveis', '{"a":"a sociedade de advogados é de natureza empresarial.","b":"os advogados sócios da sociedade de advogados respondem limitadamente por danos causados aos clientes.","c":"o registro da sociedade de advogados é realizado no Conselho Seccional da OAB onde a mesma mantiver sede.","d":"não é possível associação com advogados, sem vínculo de emprego, para participação nos resultados."}', 'c', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND ss.`name` = 'Ética e Estatuto da Advocacia' LIMIT 1), (SELECT t.`id` FROM `ebook_topics` t JOIN `subjects` s ON s.`id` = t.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND t.`order` = 4 LIMIT 1), 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 2 AND e.`year` = 2010
