SELECT '0d4883ef-933b-52fa-a228-956195e2c56e', e.`id`, 90, 'Joel é experiente advogado, inscrito há muitos anos nos quadros da OAB. Em atividade profissional, comparece à sessão de tribunal com o fito de sustentar, oralmente, recurso apresentado em prol de determinado cliente. Iniciada a sessão de julgamento, após a leitura do relatório, pelo magistrado designado para tal função no processo, dirige-se à tribuna e, regularmente, apresenta sua defesa oral. No curso do julgamento há menção, pelo Relator de data e fls. constantes dos autos processuais que se revelam incorretas. No concernente ao tema, à luz das normas estatutárias, o advogado', '{"a":"deve aguardar o final do julgamento, com a proclamação do resultado, para apresentar questão de ordem.","b":"poderá usar a palavra, pela ordem, para esclarecer questão de fato, que influencie o julgamento.","c":"não possui instrumento hábil para interromper o julgamento.","d":"após o final do julgamento deverá, mediante nova sustentação oral, indicar os erros cometidos."}', 'b', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND ss.`name` = 'Prerrogativas e Imunidades' LIMIT 1), (SELECT t.`id` FROM `ebook_topics` t JOIN `subjects` s ON s.`id` = t.`subject_id` WHERE s.`name` = 'Estatuto da Advocacia e Ética Profissional' AND t.`order` = 1 LIMIT 1), 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 2 AND e.`year` = 2010
