SELECT '60e34844-5403-54f0-ab77-25ff37afe586', e.`id`, 91, 'Antônio e Joana casaram-se pelo regime da comunhão parcial de bens. Após o casamento, Antônio tornou-se sócio de sociedade simples com 1.000 quotas representativas de 20% do capital da sociedade. Passados alguns anos, o casal veio a se separar judicialmente. Assinale a alternativa que indique o que Joana pode fazer em relação às quotas de seu ex-cônjuge.', '{"a":"Solicitar judicialmente a partilha das quotas de Antônio, ingressando na sociedade com 500 quotas ou 10% do capital social.","b":"Requerer a dissolução parcial da sociedade de modo a receber o valor de metade das quotas de Antônio calculado com base em balanço especialmente levantado, tomando-se como base a data da separação.","c":"Participar da divisão de lucros até que se liquide a sociedade, ainda que não possa nela ingressar.","d":"Requerer a dissolução da sociedade e a liquidação dos bens sociais para que, apurados os haveres dos sócios, possa receber a parte que lhe pertence das quotas de seu ex-cônjuge."}', 'c', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Empresarial' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Empresarial' AND ss.`name` = 'Tipos Societários' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 2 AND e.`year` = 2010
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 91);--> statement-breakpoint
