SELECT '8f797359-1821-5a4d-ab8d-be9ed74e66be', e.`id`, 92, 'No que se refere à cessão de quotas de sociedade empresária limitada, assinale a alternativa correta.', '{"a":"O cedente responde solidariamente com o cessionário perante a sociedade e terceiros pelas obrigações que tinha como sócio até 3 anos após averbado no registro competente a modificação do contrato social.","b":"Na omissão do contrato, o sócio pode ceder sua quota, total ou parcialmente, a quem já seja sócio, independentemente da audiência dos demais.","c":"A cessão de quotas, consubstanciada na respectiva alteração contratual, terá eficácia entre cedente e cessionário somente após a sua averbação perante o órgão competente.","d":"Na omissão do contrato, o sócio pode ceder sua quota, total ou parcialmente, para terceiro, estranho ao quadro de sócios, somente se houver a concordância da unanimidade dos demais sócios."}', 'b', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Empresarial' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Empresarial' AND ss.`name` = 'Tipos Societários' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 2 AND e.`year` = 2010
