SELECT '56c4a771-438b-5c29-a2cf-696605b32304', e.`id`, 93, 'Jogador de futebol de um importante time espanhol e titular da seleção brasileira é filmado por um celular em uma casa noturna na Espanha, em avançado estado de embriaguez. O vídeo é veiculado na internet e tem grande repercussão no Brasil. Temeroso de ser cortado da seleção brasileira, o jogador ajuíza uma ação no Brasil contra o portal de vídeos, cuja sede é na Califórnia, Estados Unidos. O juiz brasileiro', '{"a":"não é competente, porque o réu é pessoa jurídica estrangeira.","b":"terá competência porque os danos à imagem ocorreram no Brasil.","c":"deverá remeter o caso, por carta rogatória, à justiça norte-americana.","d":"terá competência porque o autor tem nacionalidade brasileira."}', 'b', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Internacional' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Internacional' AND ss.`name` = 'Direito Internacional Público' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 2 AND e.`year` = 2010
