SELECT '69c7539d-d585-55c7-a21e-865c09a685c8', e.`id`, 94, 'Um contrato internacional entre um exportador brasileiro de laranjas e o comprador americano, previu que em caso de litígio fosse utilizada a arbitragem, realizada pela Câmara de Comércio Internacional. O exportador brasileiro fez a remessa das laranjas, mas estas não atingiram a qualidade estabelecida no contrato. O comprador entrou com uma ação no Brasil para discutir o cumprimento do contrato. O juiz decidiu:', '{"a":"extinguir o feito sem julgamento de mérito, em face da cláusula arbitral.","b":"deferir o pedido, na forma requerida.","c":"indeferir o pedido porque o local do cumprimento do contrato é nos Estados Unidos.","d":"deferir o pedido, em razão da competência concorrente da justiça brasileira."}', 'a', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Internacional' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Internacional' AND ss.`name` = 'Direito Internacional Público' LIMIT 1), NULL, 'medium', true, NOW()
