SELECT '2824729a-07fa-5e9c-ab7b-0ea02e6e4c87', e.`id`, 95, 'Dentre os direitos de toda criança ou todo adolescente, o ECA assegura o de ser criado e educado no seio de sua família e, excepcionalmente, a colocação em família substituta, assegurando-lhe a convivência famíliar e comunitária. Fundando-se em tal preceito, acerca da colocação em família substituta, é correto afirmar que:', '{"a":"a colocação em família substituta far-se-á, exclusivamente, por meio da tutela ou da adoção.","b":"a guarda somente obriga seu detentor à assistência material a criança ou adolescente.","c":"o adotando não deve ter mais que 18 anos à data do pedido, salvo se já estiver sob a guarda ou tutela dos adotantes.","d":"desde que comprovem seu estado civil de casados, somente os maiores de 21 anos podem adotar."}', 'c', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito da Criança e do Adolescente' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito da Criança e do Adolescente' AND ss.`name` = 'Família Substituta e Adoção' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 2 AND e.`year` = 2010
