SELECT 'f416e379-145e-598a-aad1-d319d9709fe0', e.`id`, 96, 'Tendo por substrato legal as alterações promovidas pela Lei n. 12.010, de 2009 no tocante à adoção, assinale a afirmativa correta.', '{"a":"A morte dos adotantes não restabelece o poder familiar dos pais naturais.","b":"Para viabilizar a celeridade no processo de adoção, a legislação específica – ECA – admite a representação do adotante por procuração.","c":"Uma vez falecido o adotante no curso do procedimento de adoção e antes de prolatada a sentença, não poderá o juiz deferir a adoção, mesmo que tenha havido inequívoca manifestação de vontade do adotante.","d":"Os cartórios de registros públicos de pessoas naturais deverão fornecer certidão a qualquer requisitante, independentemente, de justificativa de seu interesse, em que conste o vínculo da adoção constituído por sentença judicial."}', 'a', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito da Criança e do Adolescente' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito da Criança e do Adolescente' AND ss.`name` = 'Família Substituta e Adoção' LIMIT 1), NULL, 'medium', true, NOW()
