SELECT '3903070e-2808-576e-ad00-3a0fd40779a6', e.`id`, 97, 'Considerando a repartição de competências ambientais estabelecida na Constituição Federal, assinale a alternativa correta.', '{"a":"Deverá ser editada lei ordinária com as normas para a cooperação entre a União e os Estados, o Distrito Federal e os Municípios para o exercício da competência comum de defesa do meio ambiente.","b":"A exigência de apresentação, no processo de licenciamento ambiental, de certidão da Prefeitura Municipal sobre a conformidade do empreendimento com a legislação de uso e ocupação do solo decorre da competência do município para o planejamento e controle do uso, do parcelamento e da ocupação do solo urbano.","c":"Legislar sobre proteção do meio ambiente e controle da poluição é de competência concorrente da União, dos Estados, do Distrito Federal e dos Municípios, com fundamento no artigo 24 da Constituição Federal.","d":"A competência executiva em matéria ambiental não alcança a aplicação de sanções administrativas por infração à legislação de meio ambiente."}', 'b', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Ambiental' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Ambiental' AND ss.`name` = 'Princípios e Política Nacional do Meio Ambiente' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 2 AND e.`year` = 2010
