SELECT 'd62a1c6e-08ff-5485-a03d-08a468df7790', e.`id`, 98, 'Diante das disposições estabelecidas pela Lei n. 9.605/98 sobre as sanções penais e administrativas derivadas de condutas e atividades lesivas ao meio ambiente, assinale a alternativa correta.', '{"a":"A desconsideração da pessoa jurídica somente será admitida se a pena restritiva de direitos se revelar inócua para os fins a que se destina.","b":"A pena restritiva de direitos da pessoa jurídica, no que tange a proibição de contratar com o poder público, terá duração equivalente ao tempo de permanência dos efeitos negativos da conduta delituosa sobre o meio ambiente.","c":"Constitui inovação da lei de crimes ambientais a excludente de antijuridicidade relativamente ao comércio não autorizado de animais da fauna silvestre voltado exclusivamente à subsistência da entidade familiar.","d":"Os tipos penais ambientais, em regra, descrevem crimes de perigo abstrato, que se consumam com a própria criação do risco, efetivo ou presumido, independentemente de qualquer resultado danoso."}', 'd', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Ambiental' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Ambiental' AND ss.`name` = 'Responsabilidade Ambiental' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 2 AND e.`year` = 2010
