SELECT '086f5d74-c27b-5968-acfc-d358b8d9eaf8', e.`id`, 99, 'Sobre o tratamento da publicidade no Código de Defesa do Consumidor, é correto afirmar que:', '{"a":"a publicidade somente vincula o fornecedor se contiver informações falsas.","b":"a publicidade que não informa sobre a origem do produto é considerada enganosa, mesmo quando não essencial para o produto.","c":"o ônus da prova da veracidade da mensagem publicitária cabe ao veículo de comunicação.","d":"é abusiva a publicidade que desrespeita valores ambientais."}', 'd', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito do Consumidor' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito do Consumidor' AND ss.`name` = 'Relação de Consumo e Sujeitos' LIMIT 1), NULL, 'medium', true, NOW()
