SELECT '446ad8c4-5bc3-56a0-a4e2-b5608b22b80f', e.`id`, 81, 'Segundo o texto da Consolidação das Leis do Trabalho, é correto afirmar que a lei de execução fiscal', '{"a":"é fonte subsidiária para a aplicação das normas na execução trabalhista.","b":"somente é fonte subsidiária para aplicação das normas na execução trabalhista caso não exista regramento sobre o assunto no Código de Processo Civil, que é a primeira fonte subsidiária da legislação processual do trabalho.","c":"somente é fonte subsidiária do Processo do Trabalho na execução das contribuições previdenciárias.","d":"somente é fonte subsidiária do Processo do Trabalho na execução das contribuições previdenciárias e sindicais."}', 'a', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Processual do Trabalho' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Processual do Trabalho' AND ss.`name` = 'Organização e Competência da Justiça do Trabalho' LIMIT 1), NULL, 'medium', true, NOW()
