SELECT 'ccf8ca26-b66e-5bb9-a91a-cec53a1d9dc1', e.`id`, 82, 'Segundo o Código Tributário Nacional, remissão é', '{"a":"uma modalidade de extinção dos créditos tributários e consiste na liberação da dívida por parte do credor, respaldada em lei autorizativa.","b":"a perda do direito de constituir o crédito tributário pelo decurso do prazo.","c":"uma modalidade de exclusão dos créditos tributários com a liberação das penalidades aplicadas ao sujeito passivo, respaldada em lei autorizativa.","d":"uma modalidade de extinção dos créditos tributários em razão da compensação de créditos entre o sujeito ativo e o sujeito passivo, respaldada em lei autorizativa."}', 'a', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Tributário' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Tributário' AND ss.`name` = 'Crédito Tributário e Lançamento' LIMIT 1), NULL, 'medium', true, NOW()
