SELECT 'ee5cb332-1a0b-5b9d-a962-677e8fdf8fbb', e.`id`, 85, 'Visando fomentar a indústria brasileira, uma nova lei, publicada em 18/02/2010, majorou a alíquota do Imposto sobre Produtos Industrializados (IPI), bem como majorou a alíquota do Imposto sobre Exportação (IE). A partir de que data a nova alíquota poderá ser exigida para o IPI e para o IE?', '{"a":"Imediatamente para ambos.","b":"No exercício financeiro seguinte para ambos.","c":"90 dias após a publicação da lei para o IPI e imediatamente para o IE.","d":"90 dias após o exercício financeiro seguinte para o IPI e no exercício financeiro seguinte para o IE."}', 'c', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Tributário' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Tributário' AND ss.`name` = 'Princípios Tributários' LIMIT 1), NULL, 'medium', true, NOW()
