SELECT 'c57db83e-07ed-5eaa-a303-f4e2276733e6', e.`id`, 86, 'Determinada pessoa, havendo arrematado imóvel em leilão judicial ocorrido em processo de execução fiscal para a cobrança de Imposto Predial Urbano, vem a sofrer a exigência pelo saldo devedor da execução não coberto pelo preço da arrematação. Essa exigência é', '{"a":"legal, pois o arrematante é sucessor do executado em relação ao imóvel, e em sua pessoa fiscal ficam sub-rogados os créditos dos tributos incidentes sobre o mesmo imóvel.","b":"ilegal, pois o crédito do exequente se sub-roga sobre o preço da arrematação, exonerando o arrematante quanto ao saldo devedor.","c":"legal, pois o valor pago pelo arrematante não foi suficiente para a cobertura da execução.","d":"legal, pois a arrematação não pode causar prejuízo ao Fisco."}', 'b', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Tributário' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Tributário' AND ss.`name` = 'Obrigação Tributária' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 3 AND e.`year` = 2011
