SELECT 'e7dab199-3e19-5eb1-a25f-bae891ea2857', e.`id`, 87, 'Nos autos de uma ação de divórcio, os ex-cônjuges, casados em regime de comunhão total de bens, dividiram o patrimônio total existente da seguinte maneira: o imóvel situado no Município X, no valor de R$ 50.000,00, pertencerá ao ex-marido, enquanto o imóvel situado no Município Y, no valor de R$ 30.000,00, pertencerá à ex-esposa. Assinale a alternativa correta quanto à tributação incidente nessa partilha.', '{"a":"O tributo a ser recolhido será o ITCMD, de competência do Estado, e incidirá sobre a base de cálculo no valor de R$ 10.000,00.","b":"O tributo a ser recolhido será o ITBI, sobre ambos os imóveis, cada qual para o município de localização do bem.","c":"O tributo a ser recolhido será o ITBI, de competência do Município, e incidirá sobre a base de cálculo no valor de R$ 10.000,00.","d":"Não há tributo a ser recolhido, pois, como o regime de casamento era o da comunhão total de bens, não há transferência de bens, mas simples repartição do patrimônio comum de cada ex-cônjuge."}', 'a', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Tributário' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Tributário' AND ss.`name` = 'Espécies Tributárias' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 3 AND e.`year` = 2011
