SELECT 'f2aee2c3-055e-5929-adcd-f04b1ac12f7d', e.`id`, 88, 'Uma construtora com sede no Município do Rio de Janeiro constrói um edifício sob regime de empreitada na cidade de Nova Iguaçu, onde não possui estabelecimento. A competência para a imposição do Imposto Municipal Sobre Serviços (ISS) caberá à municipalidade', '{"a":"do Rio de Janeiro, porque é o município onde a construtora tem a sua sede social.","b":"de Nova Iguaçu, porque é o local onde foi construído o edifício.","c":"do Rio de Janeiro, porque construção civil não é prestação de serviços.","d":"do Rio de Janeiro, porque a construtora não tem estabelecimento em Nova Iguaçu e, em razão do princípio da territorialidade, não pode ser exigido o tributo sobre contribuintes estabelecidos fora do território de cada Ente Federado."}', 'b', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Tributário' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Tributário' AND ss.`name` = 'Competência Tributária' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 3 AND e.`year` = 2011
