SELECT '598eac5f-415f-5c60-ab87-74a636c45905', e.`id`, 90, 'A Lei 9.985/2001, que instituiu o Sistema Nacional de Unidades de Conservação – SNUC, previu que as unidades de conservação devem dispor de uma zona de amortecimento definida no plano de manejo. A esse respeito, assinale a alternativa correta.', '{"a":"Os parques, como unidades de conservação de uso sustentado, não têm zona de amortecimento.","b":"As Áreas de Proteção Ambiental – APAs não precisam demarcar sua zona de amortecimento.","c":"Tanto as unidades de conservação de proteção integral como as de uso sustentado devem elaborar plano de manejo, delimitando suas zonas de amortecimento.","d":"As Reservas Particulares do Patrimônio Natural – RPPN são obrigadas a elaborar plano de manejo delimitando suas zonas de amortecimento, por conta própria e orientação técnica particular."}', 'b', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Ambiental' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Ambiental' AND ss.`name` = 'Código Florestal e Áreas Protegidas' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 3 AND e.`year` = 2011
