SELECT '3411b7f7-f1a7-5a29-a105-8e0866843328', e.`id`, 91, 'O Estudo de Impacto de Vizinhança – EIV é uma espécie do gênero Avaliação de Impacto Ambiental e está disciplinado no Estatuto da Cidade, que estabelece e enumera os instrumentos da política de desenvolvimento urbano, de acordo com seus arts. 4º e 36 a 38. A esse respeito, assinale a alternativa correta.', '{"a":"As atividades de relevante e significativo impacto ambiental que atingem mais de um Município são precedidas de estudo de impacto de vizinhança.","b":"O estudo de impacto de vizinhança só pode ser exigido em área rural pelo órgão ambiental municipal.","c":"A Avaliação de Impacto Ambiental é exigida para analisar o adensamento populacional e a geração de tráfego e demanda por transporte público advindos da edificação de um prédio.","d":"A elaboração de estudo de impacto de vizinhança não substitui a elaboração de estudo prévio de impacto ambiental, requerida nos termos da legislação ambiental."}', 'd', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Ambiental' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Ambiental' AND ss.`name` = 'Licenciamento e Avaliação de Impacto' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 3 AND e.`year` = 2011
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 91);--> statement-breakpoint
