SELECT '8ac269eb-42a9-5c56-a51e-0dd98099009f', e.`id`, 92, 'O prazo para reclamar sobre vício oculto de produto durável é de', '{"a":"90 (noventa) dias a contar da aquisição do produto.","b":"90 (noventa) dias a contar da entrega do produto.","c":"30 (trinta) dias a contar da entrega do produto.","d":"90 (noventa) dias a contar de quando ficar evidenciado o vício."}', 'd', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito do Consumidor' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito do Consumidor' AND ss.`name` = 'Responsabilidade pelo Fato e pelo Vício' LIMIT 1), NULL, 'medium', true, NOW()
