SELECT '3fd1232e-9b52-53cc-acbf-6f4ce89b6317', e.`id`, 93, 'A supressão de vegetação primária e secundária no estágio avançado de regeneração somente poderá ser autorizada em caso de utilidade pública, sendo que a vegetação secundária em estágio médio de regeneração poderá ser suprimida nos casos de utilidade pública e interesse social, em todos os casos devidamente caracterizados e motivados em procedimento administrativo próprio, quando inexistir alternativa técnica e locacional ao empreendimento proposto, conforme o disposto no art. 14 da Lei 11.428/2006, que dispõe sobre a utilização e proteção da vegetação nativa do bioma Mata Atlântica. A esse respeito, assinale a alternativa correta.', '{"a":"Um advogado de proprietário de terreno urbano afirma ser possível a obtenção de licença ambiental para edificação de condomínio residencial com supressão de Mata Atlântica com base em utilidade pública.","b":"A licença ambiental de empreendimento de relevante e significativo impacto ambiental localizado em terreno recoberto de Mata Atlântica não pode ser concedida em hipótese alguma.","c":"Um produtor de pequena propriedade ou posse rural entende que é possível a obtenção de licença ambiental para atividade agroflorestal sustentável, tendo como motivo o interesse social.","d":"Desde que obtida a autorização de supressão de vegetação de Mata Atlântica, com base na Lei 11.428/2006, não é aplicável a legislação que exige a licença ambiental, de acordo com a CRFB/88, a Lei 6.938/81 e o Decreto 99.274/90."}', 'c', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Ambiental' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Ambiental' AND ss.`name` = 'Código Florestal e Áreas Protegidas' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 3 AND e.`year` = 2011
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 93);--> statement-breakpoint
