SELECT '24dac726-059f-54d0-a3c3-2e6b4b72ea87', e.`id`, 95, 'Considerando a prática de ato infracional por criança ou adolescente, é correto afirmar que', '{"a":"a prestação de serviços comunitários consiste na realização de tarefas gratuitas de interesse geral, por período não excedente a 1 (um) ano, em entidades assistenciais, hospitais, escolas e outros estabelecimentos congêneres, bem como em programas comunitários ou governamentais.","b":"em se tratando de ato infracional com reflexos patrimoniais, a autoridade poderá determinar, se for o caso, que o adolescente restitua a coisa, promova o ressarcimento do dano, ou, por outra forma, compense o prejuízo da vítima.","c":"a internação, por constituir medida privativa de liberdade do menor, não poderá exceder o período de 5 (cinco) anos.","d":"entre as garantias processuais garantidas ao adolescente encontra-se o direito de solicitar a presença de seus pais ou responsável em qualquer fase do procedimento. Contudo, não poderá o menor ser ouvido pessoalmente pela autoridade competente, devendo em todo o caso ser assistido pelos genitores."}', 'b', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito da Criança e do Adolescente' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito da Criança e do Adolescente' AND ss.`name` = 'Medidas de Proteção e Socioeducativas' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 3 AND e.`year` = 2011
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 95);--> statement-breakpoint
INSERT INTO `exam_questions` (`id`, `exam_id`, `number`, `statement`, `alternatives`, `correct_answer`, `subject_id`, `subsubject_id`, `ebook_topic_id`, `difficulty`, `classified`, `classified_at`)
SELECT 'dc02809e-fca1-5dbb-aa53-8de09e757657', e.`id`, 96, 'Pierre de Oliveira nasceu na França, filho de pai brasileiro (que à época se encontrava em viagem privada de estudos) e mãe francesa. Viveu até os 25 anos em Paris, onde se formou em análise de sistemas e se pós-graduou em segurança de rede. Em 2007, Pierre foi convidado por uma universidade brasileira para fazer parte de um projeto de pesquisa destinado a desenvolver um sistema de segurança para uso de instituições financeiras. Embora viajasse com frequência para a França, Pierre passou a residir no Brasil, optando, em 2008, pela nacionalidade brasileira. No início de 2010, uma investigação conjunta entre as polícias brasileira e francesa descobriu que Pierre fez parte, no passado, de uma quadrilha internacional de hackers. Detido em São Paulo, ele confessou que, entre 2004 e 2005, quando ainda vivia em Paris, invadiu mais de uma vez a rede de um grande banco francês, desviando recursos para contas localizadas em paraísos fiscais. Com relação ao caso hipotético acima, é correto afirmar que', '{"a":"se a França assim requerer, Pierre poderá ser extraditado, pois cometeu crime comum sujeito à jurisdição francesa antes de optar pela nacionalidade brasileira.","b":"a critério do Ministério da Justiça, Pierre poderá ser expulso do território nacional pelo crime cometido no exterior antes do processo de aquisição da nacionalidade, a menos que tenha filho brasileiro que, comprovadamente, esteja sob sua guarda e dele dependa economicamente.","c":"Pierre poderá ser deportado para a França, a menos que peça asilo político.","d":"Pierre não poderá ser extraditado, expulso ou deportado em qualquer hipótese."}', 'd', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Internacional' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Internacional' AND ss.`name` = 'Direito Internacional Público' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 3 AND e.`year` = 2011
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 96);--> statement-breakpoint
