SELECT 'e8342dda-7a7e-50ab-a33f-b87ebc7c5ac6', e.`id`, 97, 'Com relação aos procedimentos para a perda e a suspensão do poder familiar regulados pelo Estatuto da Criança e do Adolescente, é correto afirmar que', '{"a":"a autoridade judiciária, ouvido o Ministério Público, poderá decretar liminar ou incidentalmente a suspensão do poder familiar, independentemente da gravidade do motivo.","b":"o procedimento para perda ou suspensão do poder familiar dispensa que os pais sejam ouvidos, mesmo se estes forem identificados e estiverem em local conhecido.","c":"o procedimento para perda ou suspensão do poder familiar terá início por provocação do Ministério Público ou de quem tenha legítimo interesse.","d":"em conformidade com a nova redação dada pela Lei 12.010, de 3 de agosto de 2009, o prazo máximo para a conclusão do procedimento de perda ou suspensão do poder familiar será de 180 (cento e oitenta) dias."}', 'c', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito da Criança e do Adolescente' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito da Criança e do Adolescente' AND ss.`name` = 'Família Substituta e Adoção' LIMIT 1), NULL, 'medium', true, NOW()
