SELECT '61ddd422-69b0-5657-a02c-8e4cdc7b9127', e.`id`, 98, 'Em relação aos princípios previstos no Código de Defesa do Consumidor, assinale a alternativa correta.', '{"a":"O CDC é uma norma tipificadora de condutas, prevendo expressamente o comportamento dos consumidores e dos fornecedores.","b":"A boa-fé prevista no CDC é a boa-fé subjetiva.","c":"O princípio da vulnerabilidade, que presume ser o consumidor o elo mais fraco da relação de consumo, diz respeito apenas à vulnerabilidade técnica.","d":"O princípio da transparência impõe um dever comissivo e um omissivo, ou seja, não pode o fornecedor deixar de apresentar o produto tal como ele se encontra nem pode dizer mais do que ele faz; não pode, portanto, mais existir o dolus bonus."}', 'd', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito do Consumidor' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito do Consumidor' AND ss.`name` = 'Relação de Consumo e Sujeitos' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 3 AND e.`year` = 2011
