SELECT '2b92eb91-d280-5f4c-a18e-fcca5342716d', e.`id`, 99, 'A Conferência de Bretton Woods (1944), realizada no ocaso da Segunda Guerra Mundial, é considerada um marco na história do Direito Internacional no século XX porque', '{"a":"estabeleceu as bases do sistema econômico e financeiro internacional, por meio da criação do Banco Mundial – BIRD, do Fundo Monetário Internacional – FMI e do Acordo Geral de Tarifas Aduaneiras e Comércio – GATT.","b":"inaugurou uma nova etapa na cooperação política internacional ao extinguir a Liga das Nações e transferir a Corte Internacional de Justiça para a estrutura da então recém-criada Organização das Nações Unidas – ONU.","c":"criou o sistema internacional de proteção aos direitos humanos, a partir da adoção da Declaração Universal dos Direitos Humanos, do Pacto Internacional de Direitos Civis e Políticos e do Pacto Internacional de Direitos Econômicos, Sociais e Culturais.","d":"criou o Tribunal de Nuremberg, corte ad hoc responsável pelo julgamento dos principais comandantes nazistas e seus colaboradores diretos pelos crimes de guerra cometidos durante a Segunda Guerra Mundial."}', 'a', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Internacional' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Internacional' AND ss.`name` = 'Organizações Internacionais' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 3 AND e.`year` = 2011
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 99);--> statement-breakpoint
