SELECT '743ecdcb-2c84-567e-a4ea-938141398d20', e.`id`, 100, 'Em junho de 2009, uma construtora brasileira assina, na Cidade do Cabo, África do Sul, contrato de empreitada com uma empresa local, tendo por objeto a duplicação de um trecho da rodovia que liga a Cidade do Cabo à capital do país, Pretória. As contratantes elegem o foro da comarca de São Paulo para dirimir eventuais dúvidas. Um ano depois, as partes se desentendem quanto aos critérios técnicos de medição das obras e não conseguem chegar a uma solução amigável. A construtora brasileira decide, então, ajuizar, na justiça paulista, uma ação rescisória com o objetivo de colocar termo ao contrato. Com relação ao caso hipotético acima, é correto afirmar que', '{"a":"o Poder Judiciário brasileiro não é competente para conhecer e julgar a lide, pois o foro para dirimir questões em matéria contratual é necessariamente o do local onde o contrato é assinado.","b":"o juiz brasileiro poderá conhecer e julgar a lide, mas deverá basear sua decisão na legislação sul-africana, pois os contratos se regem pela lei do local de sua assinatura.","c":"o juiz brasileiro poderá conhecer e julgar a lide, mas deverá basear sua decisão na legislação brasileira, pois um juiz brasileiro não pode ser obrigado a aplicar leis estrangeiras.","d":"o juiz brasileiro poderá conhecer e julgar a lide, mas deverá se basear na legislação brasileira, pois em litígios envolvendo brasileiros e estrangeiros aplica-se a lex fori."}', 'b', (SELECT `id` FROM `subjects` WHERE `name` = 'Direito Internacional' LIMIT 1), (SELECT ss.`id` FROM `subsubjects` ss JOIN `subjects` s ON s.`id` = ss.`subject_id` WHERE s.`name` = 'Direito Internacional' AND ss.`name` = 'Direito Internacional Público' LIMIT 1), NULL, 'medium', true, NOW()
FROM `exams` e WHERE e.`exam_number` = 3 AND e.`year` = 2011
AND NOT EXISTS (SELECT 1 FROM `exam_questions` x WHERE x.`exam_id` = e.`id` AND x.`number` = 100);--> statement-breakpoint
UPDATE `exams` e SET e.`total_questions` = (SELECT COUNT(*) FROM `exam_questions` x WHERE x.`exam_id` = e.`id`)
